#include<bits/stdc++.h>
using namespace std;
const int MOD = 1000000007;
inline int add(int a, int b) { return (a += b) >= MOD ? a - MOD : a; }
inline int mult(int a, int b) { return (int)((long long)a * b % MOD); }
inline int subtract(int a, int b) { return (a -= b) < 0 ? a + MOD : a; }
int power(long long base, int exp) {
    if(exp == 0) return 1;
    long long res = power(base, exp >> 1);
    res = mult(res, res);
    if(exp & 1) res = mult(res, base);
    return (int)res;
}
inline int lowbit(int x) { return x & -x; }

int n;
int a[10][10];
vector<vector<int>> tr; // ch transition
vector<vector<int>> prob; // q
vector<vector<int>> dp;
map<bitset<128>, int> mp;
int tot = 0;

int get_id(bitset<128> s) {
    auto it = mp.find(s);
    if(it != mp.end()) return it->second;
    int new_id = ++tot;
    mp[s] = new_id;
    tr.resize(tot + 1, vector<int>(1 << n));
    for(int mask = 0; mask < (1 << n); ++mask) {
        bitset<128> t = s;
        for(int j = 0; j < (1 << n); ++j) {
            if(!t[j]) {
                int inter = mask & j;
                while(inter) {
                    int lb = lowbit(inter);
                    if(s[j ^ lb]) {
                        t[j] = 1;
                        break;
                    }
                    inter -= lb;
                }
            }
        }
        tr[new_id][mask] = get_id(t);
    }
    return new_id;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n;
    get_id(bitset<128>(1));
    prob.assign(n, vector<int>(1 << n));
    for(int i = 0; i < n; ++i) {
        for(int j = 0; j < n; ++j) {
            cin >> a[i][j];
            a[i][j] = mult(a[i][j], power(100, MOD - 2));
        }
    }
    for(int i = 0; i < n; ++i) {
        for(int mask = 0; mask < (1 << n); ++mask) {
            prob[i][mask] = 1;
            for(int k = 0; k < n; ++k) {
                if(mask & (1 << k))
                    prob[i][mask] = mult(prob[i][mask], a[i][k]);
                else
                    prob[i][mask] = mult(prob[i][mask], subtract(1, a[i][k]));
            }
        }
    }
    dp.assign(n + 1, vector<int>(tot + 1, 0));
    dp[0][1] = 1;
    for(int i = 1; i <= n; ++i) {
        for(int st = 1; st <= tot; ++st) {
            for(int mask = 0; mask < (1 << n); ++mask) {
                int nxt = tr[st][mask];
                dp[i][nxt] = add(dp[i][nxt], mult(dp[i-1][st], prob[i-1][mask]));
            }
        }
    }
    bitset<128> full;
    for(int i = 0; i < (1 << n); ++i) full[i] = 1;
    cout << dp[n][mp[full]] << '\n';
    return 0;
}
